// Everything downstream needs stable identifiers that survive every
// success and failure branch, created before any API/OCR call is made.
// No weak fallback: a missing crypto.randomUUID must fail visibly rather
// than mint a low-entropy identity for evidence.
// The n8n JS Task Runner sandbox does not expose a bare `crypto` global
// (confirmed against the real pinned n8nio/n8n:2.33.7 image) -- the built-in
// must be required explicitly, and require() itself is denied unless
// allow-listed (NODE_FUNCTION_ALLOW_BUILTIN=crypto, set on the n8n
// container -- see docker-compose.phase1-upload-demo.yml). Same pattern as
// Flow 1a's "Build run context" nodes: a single guarded require("crypto")
// reference is reused for both the UUIDs and the pdf hash below, instead of
// an earlier round's second, unguarded require('crypto').createHash(...)
// call, which crashed this node -- and with it the whole execution, before
// any of this workflow's own error handling ever ran -- whenever
// NODE_FUNCTION_ALLOW_BUILTIN=crypto was not set (found 2026-08-25: this is
// what produced the empty HTTP 200 the missing-Gemini-credential case used
// to return).
let nodeCrypto;
try {
  nodeCrypto = require("crypto");
} catch (e) {
  nodeCrypto = undefined;
}
if (!nodeCrypto || typeof nodeCrypto.randomUUID !== "function") {
  throw new Error(
    "SECURE_UUID_UNAVAILABLE: refusing to mint a weak identifier for correlationId/processInstanceId without crypto.randomUUID() (require(\"crypto\") must be allow-listed via NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance)."
  );
}
const correlationId = nodeCrypto.randomUUID();
const processInstanceId = nodeCrypto.randomUUID();

const item = $input.first();
const body = item.json.body || {};
// "data" matches the unmodified "02.1 Encode PDF for OCR" node's binaryPropertyName.
const invoiceFile = item.binary ? item.binary.data : undefined;
const pdfSha256 = invoiceFile
  ? nodeCrypto.createHash("sha256").update(await this.helpers.getBinaryDataBuffer(0, "data")).digest("hex")
  : null;

const demoModeRequested = body.demoMode === "true" || body.demoMode === true;
const submittedOrganizationId =
  typeof body.organizationId === "string" && body.organizationId.trim() !== ""
    ? body.organizationId.trim()
    : null;
// Never a silent fallback -- only demoMode=true selects the fictional org.
const organizationId =
  submittedOrganizationId || (demoModeRequested ? "unternehmen-x-demo" : null);

// AI-execution-profile selection (2026-08-11, dev-stack/AI-selection round):
// the browser sends only a stable profile ID -- never a provider URL, model
// name, or credential. An absent/blank value stays null and is handled by
// "01.9 Resolve AI execution profile" as "unknown", never defaulted to cloud.
// Required only for a real, TCMS-attached Risk Review; a clean report
// stays a valid standalone result without it (enforced fail-closed by
// "03.4 Evaluate risk review gate", not here). Same pattern as Flow 1a's
// "01.2 Build run context": caller-supplied only, never derived from
// organizationId (the demo phase1ProfileKey is a distinct identity).
const tcmsOrganizationId =
  typeof body.tcmsOrganizationId === "string" && body.tcmsOrganizationId.trim() !== ""
    ? body.tcmsOrganizationId.trim()
    : null;

const submittedAiExecutionProfile =
  typeof body.aiExecutionProfile === "string" && body.aiExecutionProfile.trim() !== ""
    ? body.aiExecutionProfile.trim()
    : null;

return [
  {
    json: {
      correlationId,
      processInstanceId,
      tcmsOrganizationId,
      receivedAt: new Date().toISOString(),
      hasFile: Boolean(invoiceFile),
      filename: invoiceFile ? invoiceFile.fileName : null,
      mimeType: invoiceFile ? invoiceFile.mimeType : null,
      pdfSha256,
      organizationId,
      demoModeRequested,
      processingPath: "pdf_ocr",
      aiExecutionProfile: submittedAiExecutionProfile,
    },
    binary: item.binary,
  },
];

// Deterministic 4xx-shaped input/contract checks -- no OCR call has been
// made yet, so nothing here is a "technical" failure and nothing here is
// ever retried.
//
// Every branch must carry `binary` forward explicitly -- unlike an IF or
// Switch node, a Code node's returned item is a brand-new object, and
// omitting `binary` here silently drops the uploaded file for every node
// downstream (found 2026-08-11 via a live n8n execution: "02.1 Encode PDF
// for OCR" crashed with an opaque "Unknown error" because $input.first().
// binary was empty by the time it ran -- not a credential or Gemini issue
// at all, this node was the actual break in the chain).
const input = $input.first();
const ctx = input.json;

if (!ctx.hasFile) {
  return [{ json: { ...ctx, valid: false, errorCode: "MISSING_INVOICE_FILE", explanation: "No PDF binary field named 'data' was present in the upload. Not retried: this is an input/contract error, not a service failure." }, binary: input.binary }];
}
if (!ctx.organizationId) {
  return [{ json: { ...ctx, valid: false, errorCode: "ORGANIZATION_CONTEXT_REQUIRED", explanation: "organizationId was not provided and demoMode was not set. Pass organizationId explicitly, or demoMode=true to use the fictional unternehmen-x-demo organization. Not retried: this is an input/contract error, not a service failure." }, binary: input.binary }];
}
return [{ json: { ...ctx, valid: true }, binary: input.binary }];

// AI-execution-profile resolution (2026-08-11, dev-stack/AI-selection
// round). The browser sends only a stable profile ID -- provider URLs,
// model names, and credentials are resolved here, server-side, and never
// travel to or from the browser. No profile ID ever defaults to cloud:
// a missing/unknown ID is classified "unknown" and fails safely downstream
// (01.11), and an unconfigured local endpoint is classified
// "local_unavailable" rather than silently trying (and definitely never
// silently falling back to cloud).
const PROFILE_REGISTRY = {
  "local-default": {
    aiProvider: "local-openai-compatible",
    modelId: $env.LOCAL_LLM_MODEL || "local-default-model",
    modelVersion: null,
    processingLocation: "local",
    promptVersion: "flow1b-extract-v1",
  },
  "cloud-gemini": {
    aiProvider: "google-gemini",
    modelId: "gemini-2.5-pro",
    modelVersion: null,
    processingLocation: "cloud",
    promptVersion: "flow1b-extract-v1",
  },
};

const ctx = $input.first().json;
const requested = ctx.aiExecutionProfile;
const known = requested ? PROFILE_REGISTRY[requested] : null;

let profileStatus;
if (!known) {
  profileStatus = "unknown";
} else if (requested === "local-default" && !($env.LOCAL_LLM_BASE_URL || "").trim()) {
  // Configured-availability check only -- a genuine runtime connection
  // failure at call time is still caught by 02.3L's own error branch.
  profileStatus = "local_unavailable";
} else if (requested === "local-default") {
  profileStatus = "local";
} else {
  profileStatus = "cloud";
}

return [
  {
    json: {
      ...ctx,
      aiProfileStatus: profileStatus,
      resolvedProfile: known,
    },
    binary: $input.first().binary,
  },
];

const binaryPropertyName = 'data';
const result = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryPropertyName);

  result.push({
    json: {
      pdfMimeType: 'application/pdf',
      pdfBase64: buffer.toString('base64')
    }
  });
}

return result;

function extractTextFromGeminiResponse(item) {
  const j = item.json || {};

  if (
    Array.isArray(j.candidates) &&
    j.candidates[0] &&
    j.candidates[0].content &&
    Array.isArray(j.candidates[0].content.parts) &&
    j.candidates[0].content.parts[0] &&
    typeof j.candidates[0].content.parts[0].text === 'string'
  ) {
    return j.candidates[0].content.parts[0].text;
  }

  throw new Error('Could not find Gemini text output in expected response fields.');
}

function stripMarkdownFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function ensureField(obj, key) {
  return typeof obj[key] === 'string' && obj[key].trim()
    ? obj[key].trim()
    : 'not found';
}

function ensureLineItems(obj) {
  const raw = obj['Line Items'];
  if (!Array.isArray(raw)) return [];
  return raw.map((li) => ({
    Description: typeof li['Description'] === 'string' && li['Description'].trim() ? li['Description'].trim() : 'not found',
    Quantity: li['Quantity'],
    'Net Amount': li['Net Amount'],
    'VAT Rate': li['VAT Rate'],
  }));
}

const profile = $('01.9 Resolve AI execution profile').item.json.resolvedProfile;

return items.map(item => {
  const rawText = extractTextFromGeminiResponse(item);
  const cleaned = stripMarkdownFences(rawText);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Gemini output is not valid JSON. Raw output: ${cleaned}`);
  }

  const normalized = {
    'Invoice No': ensureField(parsed, 'Invoice No'),
    'Invoice Date': ensureField(parsed, 'Invoice Date'),
    'Type Code': ensureField(parsed, 'Type Code'),
    'Currency': ensureField(parsed, 'Currency'),
    'VAT-ID (Seller)': ensureField(parsed, 'VAT-ID (Seller)'),
    'VAT-ID (Buyer)': ensureField(parsed, 'VAT-ID (Buyer)'),
    'Tax ID (Seller)': ensureField(parsed, 'Tax ID (Seller)'),
    'Tax ID (Buyer)': ensureField(parsed, 'Tax ID (Buyer)'),
    'Name (Seller)': ensureField(parsed, 'Name (Seller)'),
    'Address (Seller)': ensureField(parsed, 'Address (Seller)'),
    'Zip (Seller)': ensureField(parsed, 'Zip (Seller)'),
    'City (Seller)': ensureField(parsed, 'City (Seller)'),
    'Country (Seller)': ensureField(parsed, 'Country (Seller)'),
    'Name (Buyer)': ensureField(parsed, 'Name (Buyer)'),
    'Address (Buyer)': ensureField(parsed, 'Address (Buyer)'),
    'Zip (Buyer)': ensureField(parsed, 'Zip (Buyer)'),
    'City (Buyer)': ensureField(parsed, 'City (Buyer)'),
    'Country (Buyer)': ensureField(parsed, 'Country (Buyer)'),
    'Supply Description': ensureField(parsed, 'Supply Description'),
    'Delivery Date': ensureField(parsed, 'Delivery Date'),
    'Period Start': ensureField(parsed, 'Period Start'),
    'Period End': ensureField(parsed, 'Period End'),
    'Net Total': parsed['Net Total'],
    'Tax Basis': parsed['Tax Basis'],
    'Tax Amount': parsed['Tax Amount'],
    'Gross Total': parsed['Gross Total'],
    'Payable Amount': parsed['Payable Amount'],
    'Charge Total': parsed['Charge Total'],
    'Allowance Total': parsed['Allowance Total'],
    'Prepaid Amount': parsed['Prepaid Amount'],
    'Rounding Amount': parsed['Rounding Amount'],
    'Line Items': ensureLineItems(parsed)
  };

  return {
    json: {
      invoice_extracted: normalized,
      gemini_raw_text: rawText,
      aiMeta: {
        aiProvider: profile.aiProvider,
        modelId: profile.modelId,
        modelVersion: profile.modelVersion,
        processingLocation: profile.processingLocation,
        promptVersion: profile.promptVersion,
        fallbackUsed: false,
      },
    }
  };
});

const binaryPropertyName = 'data';
const result = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryPropertyName);

  result.push({
    json: {
      pdfMimeType: 'application/pdf',
      pdfBase64: buffer.toString('base64')
    }
  });
}

return result;

function extractTextFromLocalResponse(item) {
  const j = item.json || {};
  if (
    Array.isArray(j.choices) &&
    j.choices[0] &&
    j.choices[0].message &&
    typeof j.choices[0].message.content === 'string'
  ) {
    return j.choices[0].message.content;
  }
  throw new Error('Could not find local LLM text output in expected choices[0].message.content field.');
}

function stripMarkdownFences(text) {
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function ensureField(obj, key) {
  return typeof obj[key] === 'string' && obj[key].trim()
    ? obj[key].trim()
    : 'not found';
}

function ensureLineItems(obj) {
  const raw = obj['Line Items'];
  if (!Array.isArray(raw)) return [];
  return raw.map((li) => ({
    Description: typeof li['Description'] === 'string' && li['Description'].trim() ? li['Description'].trim() : 'not found',
    Quantity: li['Quantity'],
    'Net Amount': li['Net Amount'],
    'VAT Rate': li['VAT Rate'],
  }));
}

const profile = $('01.9 Resolve AI execution profile').item.json.resolvedProfile;

return items.map(item => {
  const rawText = extractTextFromLocalResponse(item);
  const cleaned = stripMarkdownFences(rawText);

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Local LLM output is not valid JSON. Raw output: ${cleaned}`);
  }

  const normalized = {
    'Invoice No': ensureField(parsed, 'Invoice No'),
    'Invoice Date': ensureField(parsed, 'Invoice Date'),
    'Type Code': ensureField(parsed, 'Type Code'),
    'Currency': ensureField(parsed, 'Currency'),
    'VAT-ID (Seller)': ensureField(parsed, 'VAT-ID (Seller)'),
    'VAT-ID (Buyer)': ensureField(parsed, 'VAT-ID (Buyer)'),
    'Tax ID (Seller)': ensureField(parsed, 'Tax ID (Seller)'),
    'Tax ID (Buyer)': ensureField(parsed, 'Tax ID (Buyer)'),
    'Name (Seller)': ensureField(parsed, 'Name (Seller)'),
    'Address (Seller)': ensureField(parsed, 'Address (Seller)'),
    'Zip (Seller)': ensureField(parsed, 'Zip (Seller)'),
    'City (Seller)': ensureField(parsed, 'City (Seller)'),
    'Country (Seller)': ensureField(parsed, 'Country (Seller)'),
    'Name (Buyer)': ensureField(parsed, 'Name (Buyer)'),
    'Address (Buyer)': ensureField(parsed, 'Address (Buyer)'),
    'Zip (Buyer)': ensureField(parsed, 'Zip (Buyer)'),
    'City (Buyer)': ensureField(parsed, 'City (Buyer)'),
    'Country (Buyer)': ensureField(parsed, 'Country (Buyer)'),
    'Supply Description': ensureField(parsed, 'Supply Description'),
    'Delivery Date': ensureField(parsed, 'Delivery Date'),
    'Period Start': ensureField(parsed, 'Period Start'),
    'Period End': ensureField(parsed, 'Period End'),
    'Net Total': parsed['Net Total'],
    'Tax Basis': parsed['Tax Basis'],
    'Tax Amount': parsed['Tax Amount'],
    'Gross Total': parsed['Gross Total'],
    'Payable Amount': parsed['Payable Amount'],
    'Charge Total': parsed['Charge Total'],
    'Allowance Total': parsed['Allowance Total'],
    'Prepaid Amount': parsed['Prepaid Amount'],
    'Rounding Amount': parsed['Rounding Amount'],
    'Line Items': ensureLineItems(parsed)
  };

  return {
    json: {
      invoice_extracted: normalized,
      raw_text: rawText,
      aiMeta: {
        aiProvider: profile.aiProvider,
        modelId: profile.modelId,
        modelVersion: profile.modelVersion,
        processingLocation: profile.processingLocation,
        promptVersion: profile.promptVersion,
        fallbackUsed: false,
      },
    }
  };
});

// Assembles the canonical invoice contract in
// facturx/phase1/schemas/canonical_invoice.schema.json exactly (same
// document/extraction/invoice/fieldEvidence shape, schemaVersion "1.0.0")
// so this node's output can be submitted directly to the real Phase 1 API's
// POST /v1/invoices/process-extracted (see "03.1 Run DigiTax controls"
// below) -- this is the API-convergence fix for the A1 review's "Flow 1b
// does not use the canonical Phase-1 control API" finding. Buyer master
// data is no longer looked up here at all: the real API resolves
// organization context (and evaluates ORG-001 against it) itself, from
// organizationId alone, so there is nothing left in n8n to keep in sync by
// hand.
//
// Shared by both provider lanes (2026-08-11, dev-stack/AI-selection round;
// expanded to the full schema 2026-08-18): "02.5 Parse OCR/LLM output"
// (cloud) and "02.5L Parse local OCR/LLM output" (local) both emit the
// same {invoice_extracted, aiMeta} shape, so this single node produces one
// identical canonical contract regardless of which lane ran -- per the
// AI-selection spec's convergence requirement.
const PLACEHOLDER_FOUND_CONFIDENCE = 0.85;
const parsed = $input.first().json;
const g = parsed.invoice_extracted;

function emit(rawValue, locator) {
  const found = typeof rawValue === "string" && rawValue.trim() && rawValue.trim().toLowerCase() !== "not found";
  return {
    value: found ? rawValue.trim() : null,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

// Coerces a model-reported amount (already a JSON number in the happy
// path, but defensively also accepts a string with German "1.234,56" or
// plain "1234.56" formatting) to a JS number, or null if not parseable.
function numOrNull(v) {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v !== "string") return null;
  const t = v.trim();
  if (!t || t.toLowerCase() === "not found") return null;
  const cleaned = t.replace(/[^\d,.-]/g, "");
  const normalized = cleaned.includes(",") && cleaned.includes(".")
    ? cleaned.replace(/\./g, "").replace(",", ".")
    : cleaned.replace(",", ".");
  const n = parseFloat(normalized);
  return Number.isFinite(n) ? n : null;
}

function emitNum(rawValue, locator) {
  const n = numOrNull(rawValue);
  const found = n !== null;
  return {
    value: n,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

function emitCode(rawValue, locator, validator) {
  const candidate = typeof rawValue === "string" ? rawValue.trim().toUpperCase() : null;
  const value = candidate && validator(candidate) ? candidate : null;
  const found = value !== null;
  return {
    value,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}
const isCurrency = (v) => /^[A-Z]{3}$/.test(v);
const isCountry = (v) => /^[A-Z]{2}$/.test(v);

const invoiceNumber = emit(g["Invoice No"], "invoice.invoiceNumber");
const issueDate = emit(g["Invoice Date"], "invoice.issueDate");
const typeCode = emit(g["Type Code"], "invoice.typeCode");
const currency = emitCode(g["Currency"], "invoice.currency", isCurrency);

const supplierName = emit(g["Name (Seller)"], "invoice.supplier.name");
const supplierVatId = emit(g["VAT-ID (Seller)"], "invoice.supplier.vatId");
const supplierTaxId = emit(g["Tax ID (Seller)"], "invoice.supplier.taxId");
const supplierStreet = emit(g["Address (Seller)"], "invoice.supplier.address.street");
const supplierPostal = emit(g["Zip (Seller)"], "invoice.supplier.address.postalCode");
const supplierCity = emit(g["City (Seller)"], "invoice.supplier.address.city");
const supplierCountry = emitCode(g["Country (Seller)"], "invoice.supplier.address.countryCode", isCountry);

const buyerName = emit(g["Name (Buyer)"], "invoice.buyer.name");
const buyerVatId = emit(g["VAT-ID (Buyer)"], "invoice.buyer.vatId");
const buyerTaxId = emit(g["Tax ID (Buyer)"], "invoice.buyer.taxId");
const buyerStreet = emit(g["Address (Buyer)"], "invoice.buyer.address.street");
const buyerPostal = emit(g["Zip (Buyer)"], "invoice.buyer.address.postalCode");
const buyerCity = emit(g["City (Buyer)"], "invoice.buyer.address.city");
const buyerCountry = emitCode(g["Country (Buyer)"], "invoice.buyer.address.countryCode", isCountry);

const supplyDescription = emit(g["Supply Description"], "invoice.supply.description");
const deliveryDate = emit(g["Delivery Date"], "invoice.supply.deliveryDate");
const periodStart = emit(g["Period Start"], "invoice.supply.periodStart");
const periodEnd = emit(g["Period End"], "invoice.supply.periodEnd");

const lineNet = emitNum(g["Net Total"], "invoice.totals.lineNet");
const taxBasis = emitNum(g["Tax Basis"], "invoice.totals.taxBasis");
const taxAmount = emitNum(g["Tax Amount"], "invoice.totals.taxAmount");
const grossAmount = emitNum(g["Gross Total"], "invoice.totals.grossAmount");
const payableAmount = emitNum(g["Payable Amount"], "invoice.totals.payableAmount");
const chargeTotal = emitNum(g["Charge Total"], "invoice.totals.chargeTotal");
const allowanceTotal = emitNum(g["Allowance Total"], "invoice.totals.allowanceTotal");
const prepaidAmount = emitNum(g["Prepaid Amount"], "invoice.totals.prepaidAmount");
const roundingAmount = emitNum(g["Rounding Amount"], "invoice.totals.roundingAmount");

const lineItems = Array.isArray(g["Line Items"])
  ? g["Line Items"].map((li) => ({
      description: (typeof li["Description"] === "string" && li["Description"].trim() && li["Description"].trim().toLowerCase() !== "not found")
        ? li["Description"].trim()
        : null,
      quantity: numOrNull(li["Quantity"]),
      netAmount: numOrNull(li["Net Amount"]),
      vatRate: numOrNull(li["VAT Rate"]),
    }))
  : [];

const fieldEvidence = {
  "invoice.invoiceNumber": invoiceNumber.evidence,
  "invoice.issueDate": issueDate.evidence,
  "invoice.typeCode": typeCode.evidence,
  "invoice.currency": currency.evidence,
  "invoice.supplier.name": supplierName.evidence,
  "invoice.supplier.vatId": supplierVatId.evidence,
  "invoice.supplier.taxId": supplierTaxId.evidence,
  "invoice.supplier.address.street": supplierStreet.evidence,
  "invoice.supplier.address.postalCode": supplierPostal.evidence,
  "invoice.supplier.address.city": supplierCity.evidence,
  "invoice.supplier.address.countryCode": supplierCountry.evidence,
  "invoice.buyer.name": buyerName.evidence,
  "invoice.buyer.vatId": buyerVatId.evidence,
  "invoice.buyer.taxId": buyerTaxId.evidence,
  "invoice.buyer.address.street": buyerStreet.evidence,
  "invoice.buyer.address.postalCode": buyerPostal.evidence,
  "invoice.buyer.address.city": buyerCity.evidence,
  "invoice.buyer.address.countryCode": buyerCountry.evidence,
  "invoice.supply.description": supplyDescription.evidence,
  "invoice.supply.deliveryDate": deliveryDate.evidence,
  "invoice.supply.periodStart": periodStart.evidence,
  "invoice.supply.periodEnd": periodEnd.evidence,
  "invoice.totals.lineNet": lineNet.evidence,
  "invoice.totals.taxBasis": taxBasis.evidence,
  "invoice.totals.taxAmount": taxAmount.evidence,
  "invoice.totals.grossAmount": grossAmount.evidence,
  "invoice.totals.payableAmount": payableAmount.evidence,
  "invoice.totals.chargeTotal": chargeTotal.evidence,
  "invoice.totals.allowanceTotal": allowanceTotal.evidence,
  "invoice.totals.prepaidAmount": prepaidAmount.evidence,
  "invoice.totals.roundingAmount": roundingAmount.evidence,
};

const invoice = {
  invoiceNumber: invoiceNumber.value,
  issueDate: issueDate.value,
  typeCode: typeCode.value,
  currency: currency.value,
  supplier: {
    name: supplierName.value,
    address: {
      street: supplierStreet.value,
      postalCode: supplierPostal.value,
      city: supplierCity.value,
      countryCode: supplierCountry.value,
    },
    taxId: supplierTaxId.value,
    vatId: supplierVatId.value,
  },
  buyer: {
    name: buyerName.value,
    address: {
      street: buyerStreet.value,
      postalCode: buyerPostal.value,
      city: buyerCity.value,
      countryCode: buyerCountry.value,
    },
    taxId: buyerTaxId.value,
    vatId: buyerVatId.value,
  },
  supply: {
    description: supplyDescription.value,
    deliveryDate: deliveryDate.value,
    periodStart: periodStart.value,
    periodEnd: periodEnd.value,
  },
  totals: {
    lineNet: lineNet.value,
    taxBasis: taxBasis.value,
    taxAmount: taxAmount.value,
    grossAmount: grossAmount.value,
    payableAmount: payableAmount.value,
    chargeTotal: chargeTotal.value,
    allowanceTotal: allowanceTotal.value,
    prepaidAmount: prepaidAmount.value,
    roundingAmount: roundingAmount.value,
  },
  lineItems,
};

const ctx = $('01.2 Build run context').item.json;

// document.sha256 is computed once upstream in "01.2 Build run context"
// from the same uploaded buffer this normalization ultimately describes;
// this node only ever runs after "01.4 Has valid upload?" confirmed a file
